def quran_rows():
    rows = []
    report = {(r["file"], r["ref"]): r for r in json.loads((OUT / "مطابقة-القرآن.json").read_text(encoding="utf-8"))}
    for f in sorted((BOOK / "الافتتاحية").glob("*.md")) + [BOOK / "00-كلمة-المؤلف.md"]:
        loc = CH.get(f.name[:2], "كلمة المؤلف" if f.name.startswith("00-ك") else "التمهيد")
        for m in re.finditer(r"﴿([^﴾]+)﴾\s*(?:\(([^)]+)\))?", f.read_text(encoding="utf-8")):
            words = m.group(1).split()
            text = " ".join(words[:6]) + ("…" if len(words) > 6 else "")
            ref = (m.group(2) or "").strip()
            key = (f.name, re.sub(r"\s*[–-]\s*", "–", ref))
            ok = key in report and report[key]["result"].startswith("مطابق")
            rows.append(("", loc, "قرآن", text, "نص", "", ref or "بلا إحالة في المتن",
                         "مصحف المدينة النبوية، رواية حفص (الرسم العثماني)", "", "", "", "", "", m.group(1),
                         "ok" if ok else "incomplete", "التوثيق" if ok else "العثور",
                         "طوبق الرسم والإحالة على نصّين عثمانيين مستقلّين (quran.com، alquran.cloud)" if ok else "تُطابق الإحالة"))
    return rows


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    spans = {r["id"]: r for r in json.loads((OUT / "مطابقة-النقول.json").read_text(encoding="utf-8"))}
    table = []
    for i, row in enumerate(quran_rows() + ROWS, 1):
        vid, loc, kind, text, form, who, src, ed, editor, part, page, num, grade, variants, state, stage, note = row[:17]
        compared = ""
        if kind == "قرآن":
            compared, variants = variants, ""  # for the Qur'an the compared text is the Uthmani text itself
        elif vid in spans:
            rec = spans[vid]
            if rec.get("scan"):
                compared = "على المطبوع: " + rec["scan"]["where"] + " — " + rec["scan"]["note"]
            elif rec["hits"]:
                best = max(rec["hits"], key=lambda h: h["ratio"])
                compared = best["span"][:300]
        if state in ("ok", "variant") and kind != "قرآن" and vid not in ON_PRINT:
            basis = "طوبق على نسخةٍ رقمية موافقةٍ للمطبوع" + ("، وعلى طبعتين مستقلّتين" if kind.startswith(("حديث", "أثر")) else "")
            note = "؛ ".join(x for x in (basis + "؛ بقيت مطابقة اللفظ والصفحة على مصوّرة الطبعة المعتمدة؛ والحالة بعدها: "
                                         + STATE[state].split(" — ")[0], note) if x)
            state = "incomplete"
        elif vid in SCANNED:
            sc = SCANNED[vid]
            compared = f"على المطبوع: {sc['edition']}، ص{sc['printed']} (المصوّرة: {sc['url']})"
            also = sc.get("also")
            also = f"وطوبق الموضع الثاني على {also['edition']}، ص{also['printed']}: {also['text_read']}" if also else ""
            note = "؛ ".join(x for x in (f"طوبق على مصوّرة المطبوع: الصفحة {sc['page_read']}، والنص {sc['text_read']}", also, note) if x)
        elif vid in ON_PRINT:
            note = "؛ ".join(x for x in ("طوبق على مصوّرة المطبوع", note) if x and "طوبق على مصوّرة المطبوع" not in note) or note
        table.append([f"م١-{str(i).zfill(3).translate(AR)}", loc, kind, text, form, who, src, ed, editor, part, page, num, grade,
                      compared, variants, STATE[state], stage, FIRST if stage != "العثور" else "", "", note])
    with open(OUT / "سجل-النقول.tsv", "w", encoding="utf-8") as fh:
        fh.write("\t".join(FIELDS) + "\n")
        for r in table:
            fh.write("\t".join(c.replace("\t", " ").replace("\n", " ") for c in r) + "\n")
    counts = {}
    for r in table:
        counts[r[15]] = counts.get(r[15], 0) + 1
    view = [0, 1, 2, 3, 5, 6, 9, 10, 11, 12, 15, 16]
    md = ["# السجلّ المركزي للنقول: افتتاحية المجلد الأول", "",
          "يُولَّد من `pdf/ledger.py`. الحقول والحالات في الجزء التاسع من الدليل (الباب ٤٦، وتعديله في الباب ٧٣). "
          "والملفّ الكامل بحقوله العشرين في `سجل-النقول.tsv`.", "",
          "**الحالات الآن:** " + "، ".join(f"{k}: {str(v).translate(AR)}" for k, v in counts.items()) + ".", "",
          "**المرحلة:** كُتبت حواشي المواد كلها على ما ثبت بالمطابقة، فبلغت مرحلة «التوثيق». "
          "ولا تكون الحالة «متحقّق» إلا لما طوبق لفظه على الطبعة المعتمدة نفسها (مصوّرةً أو ورقًا)، وللقرآن على النص العثماني "
          "لمصحف المدينة؛ وما طوبق على نسخةٍ رقمية موافقةٍ للمطبوع بقي «توثيقًا ناقصًا» حتى تُرى المصوّرة (الباب ٤٨). "
          "ثم لا يعبر نصٌّ البوابة التاسعة حتى يوقّع المراجع الثاني حقل «المراجع النهائي». فالافتتاحية طبعةُ مراجعة.", "",
          "| " + " | ".join(FIELDS[i] for i in view) + " |", "|" + "---|" * len(view)]
    for r in table:
        md.append("| " + " | ".join(r[i].replace("|", "／") for i in view) + " |")
    (OUT / "سجل-النقول.md").write_text("\n".join(md) + "\n", encoding="utf-8")
    print(len(table), "entries;", counts)


if __name__ == "__main__":
    main()
